def calculate_historical_lines(apps, schema_editor):
    Invoice = apps.get_model('purchases', 'Invoice')
    InvoiceLine = apps.get_model('purchases', 'InvoiceLine')
    alias = schema_editor.connection.alias
    for invoice in Invoice.objects.using(alias).iterator():
        lines = InvoiceLine.objects.using(alias).filter(invoice_id=invoice.pk).values_list('quantity', 'unit_price')
        amounts = [quantity * unit_price for quantity, unit_price in lines]
        if not amounts:
            continue
        net = sum(amounts)
        vat = int((Decimal(net) * Decimal('0.19')).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        if net + vat > 2**63 - 1:
            continue
        Invoice.objects.using(alias).filter(pk=invoice.pk).update(
            net_total=net, vat_total=vat, calculated_total=net + vat,
        )


